head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/



	//----W-Craft WebSquare 변환 확인: include----//
include("../js/utils.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/libRoundPanel.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/common.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/stf.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/session.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/controlResize.js"); // 화면 리사이징

scwin.vScrenID = "ULDFIS00200_14.gfm";
scwin.vKisCd = ""; // 조회조건 기업코드
scwin.vAcntclsDt = "";
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
}; // 조회조건 결산일자

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    // 결산일자 조회

	//----W-Craft WebSquare 변환 확인: fn_SrchAcntclsDt----//
    $c.frame.path("../frame_head").fn_SrchAcntclsDt();
};


/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dts_MajProdPrcTrend1.removeAll();
    dts_MajProdPrcTrend2.removeAll();
};


/**
 *  조회조건 유효성 체크
 */
scwin.fn_ChkValid = function() {
    //필수항목 체크.

	//----W-Craft WebSquare 변환 확인: fn_GetKisCd----//
    scwin.vKisCd = $c.frame.path("../frame_head").fn_GetKisCd();

	//----W-Craft WebSquare 변환 확인: fn_GetAcntclsDt----//
    scwin.vAcntclsDt = $c.frame.path("../frame_head").fn_GetAcntclsDt();
    if (scwin.vKisCd == "" || scwin.vAcntclsDt == "") {
        return false;
    }
    return true;
};


/**
 * 주요제품가격동향 조회
 */
scwin.fn_Search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_MajProdPrcTrend);

    // 최근 3년 결산일자 조회
    scwin.fn_SearchStdDt();
};


/**
 * 최근 3년 결산일자 조회
 */
scwin.fn_SearchStdDt = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.majProdPrcTrend1" + "&outputMessageId=FIS_PROD_BZ_COMPST1" + "&param01=" + scwin.vKisCd + "&param02=" + scwin.vAcntclsDt;
    dts_MajProdPrcTrend1.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_MajProdPrcTrend1.Reset();
};


/**
 * 주요제품가격동향  조회
 */
scwin.fn_SearchProdBzCompst = function() {
    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_MajProdPrcTrend);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.majProdPrcTrend2" + "&outputMessageId=FIS_MAJ_PROD_PRC_TREND" + "&param01=" + scwin.vKisCd + "&param02=" + dts_MajProdPrcTrend1.getCellData(1, "STD_DT") + "&param03=" + dts_MajProdPrcTrend1.getCellData(2, "STD_DT") + "&param04=" + dts_MajProdPrcTrend1.getCellData(3, "STD_DT");
    dts_MajProdPrcTrend2.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_MajProdPrcTrend2.Reset();
};


/**
 * 그리드 타이틀 세팅.
 */
scwin.fn_SetGrdTitle = function() {
    $c.cm.setColumnProp(grd_MajProdPrcTrend, "YYYY1", "Name", $c.stf.FormatDateEx(dts_MajProdPrcTrend1.getCellData(1, "STD_DT")));
    $c.cm.setColumnProp(grd_MajProdPrcTrend, "YYYY2", "Name", $c.stf.FormatDateEx(dts_MajProdPrcTrend1.getCellData(2, "STD_DT")));
    $c.cm.setColumnProp(grd_MajProdPrcTrend, "YYYY3", "Name", $c.stf.FormatDateEx(dts_MajProdPrcTrend1.getCellData(3, "STD_DT")));
};


/**
 *  엑셀파일다운로드
 */
scwin.fn_excel_download = function() {
    if (dts_MajProdPrcTrend2.getTotalRow() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.data.downloadGridViewExcel(grd_MajProdPrcTrend, "주요제품가격동향", "", "8");
};
scwin.gform_onload = function() {
    scwin.fn_Init();
};
scwin.dts_MajProdPrcTrend1_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_MajProdPrcTrend);
    $c.stf.alert_error(dts_MajProdPrcTrend1);
};
scwin.dts_MajProdPrcTrend1_OnLoadCompleted = function(rowcount) {
    if (dts_MajProdPrcTrend1.errorMsg) {
        $c.cm.CloseWin(-1, grd_MajProdPrcTrend);
        alert(dts_MajProdPrcTrend1.errorMsg);
        return;
    }
    // 그리드 타이틀 세팅.
    scwin.fn_SetGrdTitle();

    // 제품및 사업구성 조회
    scwin.fn_SearchProdBzCompst();
};
scwin.dts_MajProdPrcTrend2_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_MajProdPrcTrend);
    $c.stf.alert_error(dts_MajProdPrcTrend2);
};
scwin.dts_MajProdPrcTrend2_OnLoadCompleted = function(rowcount) {
    if (dts_MajProdPrcTrend2.errorMsg) {
        alert(dts_MajProdPrcTrend2.errorMsg);
    }
    $c.cm.CloseWin(rowcount, grd_MajProdPrcTrend);
};
